// Node 13: Chuẩn hóa & Định dạng Bài Báo
const firecrawlData = $input.first().json || {};
let currentArticle = {};
try {
  currentArticle = $('10. Duyệt từng Bài Viết Mới').item.json;
} catch(e) {
  try {
    currentArticle = $('10. Duyệt từng Bài Viết Mới').first().json;
  } catch(err) {
    currentArticle = {};
  }
}

const metadata = firecrawlData.data?.metadata || {};
const markdown = firecrawlData.data?.markdown || firecrawlData.data?.content || '';

// 1. Trích xuất Tiêu đề bài viết thực tế (Ưu tiên heading trong markdown để tránh tiêu đề trang chung chung)
let title = '';
if (markdown) {
  const headingMatch = markdown.match(/^#{1,3}\s+(.+)$/m);
  if (headingMatch && headingMatch[1].trim().length > 5) {
    const cand = headingMatch[1].replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').trim();
    if (!['tin tức', 'thống kê', 'tin cùng tổ chức', 'tin khác', 'menu', 'trang chủ'].includes(cand.toLowerCase())) {
      title = cand;
    }
  }
}
if (!title) {
  title = metadata.title || metadata.ogTitle || '';
}
if (!title) {
  title = 'Bài viết từ ' + (currentArticle.source_name || 'Nguồn tin');
}

// 2. Trích xuất tóm tắt sơ bộ từ thẻ mô tả hoặc đoạn đầu nội dung
let summary = metadata.description || metadata.ogDescription || '';
if (!summary && markdown) {
  const cleanMd = markdown.replace(/^#+.*$/gm, '').replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').trim();
  summary = cleanMd.slice(0, 300).trim();
  if (cleanMd.length > 300) summary += '...';
}
if (!summary) {
  summary = 'Nội dung cập nhật từ ' + (currentArticle.source_name || '');
}

// 3. Hàm băm title thuần
function createHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16);
}

const cleanTitle = (title || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const titleHash = createHash(cleanTitle);

return [{
  json: {
    title: title.trim(),
    url: currentArticle.article_url || metadata.sourceURL || metadata.url || '',
    summary: summary.trim(),
    content_raw: markdown.slice(0, 30000),
    key_points: [],
    source_name: currentArticle.source_name || metadata.source || '',
    source_category: currentArticle.source_category || 'Tin tức',
    source_url: currentArticle.source_url || '',
    sentiment: 'Trung lập',
    tags: [currentArticle.source_category || 'Tài chính'],
    title_hash: titleHash,
    published_date: metadata.publishedTime || null
  }
}];

// Nhập thông tin nguồn cào cần thêm ở đây:
// Bạn có thể thêm 1 hoặc nhiều nguồn cùng lúc
return [
  {
    json: {
      source_name: 'VnExpress - Kinh doanh',
      source_category: 'Báo Tài chính VN',
      source_url: 'https://vnexpress.net/kinh-doanh'
    }
  }
];
